import{_ as e,C as s,o as n,c as d,j as t,E as l,a as r,a2 as o}from"./chunks/framework.Dsdg6H41.js";const z=JSON.parse('{"title":"8-hafta (Mentor)","description":"","frontmatter":{"title":"8-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":8,"bob":"III-bob · Algoritmlash, Flowalgorithm va dasturlash asoslari","lessons":[{"g":22,"title":"22-dars: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","lead":"Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq","link":"/mentor/8-sinf-cs/hafta-08/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-08/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-08/dars-1-test.html"},{"g":23,"title":"23-dars: Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash","lead":"Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash","link":"/mentor/8-sinf-cs/hafta-08/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-08/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-08/dars-2-test.html"},{"g":24,"title":"24-dars: Flowalgorithmda chiziqli algoritmlar yaratish","lead":"Flowalgorithmda chiziqli algoritmlar yaratish","link":"/mentor/8-sinf-cs/hafta-08/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-08/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-08/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-08/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-08/index.md","filePath":"mentor/8-sinf-cs/hafta-08/index.md"}'),h={name:"mentor/8-sinf-cs/hafta-08/index.md"},c={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},u={id:"baholash-mezoni-1",tabindex:"-1"};function y(b,a,q,v,k,f){const i=s("Icon");return n(),d("div",null,[t("div",c,[t("h2",g,[l(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 8-hafta<br><strong>Darslar:</strong> 22, 23, 24<br><strong>Topshirish muddati:</strong> Keyingi darsga qadar (9-hafta, 1-dars)</p><hr><h2 id="_1-topshiriq-dastur-mantiqi-va-ipo-modeli-tahlili-22-dars-·-o-rta" tabindex="-1">1-topshiriq: Dastur mantiqi va IPO modeli tahlili (22-dars) · o&#39;rta <a class="header-anchor" href="#_1-topshiriq-dastur-mantiqi-va-ipo-modeli-tahlili-22-dars-·-o-rta" aria-label="Permalink to &quot;1-topshiriq: Dastur mantiqi va IPO modeli tahlili (22-dars) · o&#39;rta&quot;">​</a></h2><ol><li>Kundalik hayotingizda foydalaniladigan quyidagi 3 ta qurilma yoki tizim uchun IPO (Input — Process — Output) modelini daftaringizga jadval ko&#39;rinishida yozing: <ul><li>Bankomat (pul yechish jarayoni)</li><li>Avtomobil spidometri (tezlikni ko&#39;rsatish)</li><li>Qidiruv tizimi (Google yoki Yandexda ma&#39;lumot izlash)</li></ul></li><li>Flowgorithmda o&#39;zingiz haqingizda ma&#39;lumot chiqaruvchi loyiha tuzing: Foydalanuvchidan ismi va sevimli mashg&#39;ulotini so&#39;rab, konsolga <code>&quot;Salom, &quot; &amp; ism &amp; &quot;! Sizning qiziqishingiz — &quot; &amp; mashgulot &amp; &quot; ekanligidan xursandmiz!&quot;</code> deb chiqaring.</li></ol><hr><h2 id="_2-topshiriq-ma-lumot-turlari-va-declare-assign-23-dars-·-o-rta" tabindex="-1">2-topshiriq: Ma&#39;lumot turlari va Declare/Assign (23-dars) · o&#39;rta <a class="header-anchor" href="#_2-topshiriq-ma-lumot-turlari-va-declare-assign-23-dars-·-o-rta" aria-label="Permalink to &quot;2-topshiriq: Ma&#39;lumot turlari va Declare/Assign (23-dars) · o&#39;rta&quot;">​</a></h2><ol><li>Quyidagi ma&#39;lumotlar uchun Flowgorithmda qaysi ma&#39;lumot turi (<code>Integer</code>, <code>Real</code>, <code>String</code>, <code>Boolean</code>) tanlanishini daftaringizga yozing: <ul><li>Sinfdagi o&#39;quvchilar soni</li><li>O&#39;quvchining bo&#39;yi (masalan: 1.68 metr)</li><li>Maktab nomi</li><li>Bugun darsga keldimi yoki yo&#39;qmi (ha/yo&#39;q)</li><li>Nonning narxi (so&#39;m)</li></ul></li><li>Flowgorithmda Harorat konvertori loyihasini yarating: Foydalanuvchi havo haroratini Selsiyda kiritadi, dastur uni Farengeyt ($F = C \\times 1.8 + 32$) shkalasiga o&#39;tkazib natijani ko&#39;rsatadi. O&#39;zgaruvchilarni to&#39;g&#39;ri turda (<code>Real</code>) e&#39;lon qiling.</li></ol><hr><h2 id="_3-topshiriq-to-liq-chiziqli-algoritm-loyihasi-24-dars-·-qiyin" tabindex="-1">3-topshiriq: To&#39;liq chiziqli algoritm loyihasi (24-dars) · qiyin <a class="header-anchor" href="#_3-topshiriq-to-liq-chiziqli-algoritm-loyihasi-24-dars-·-qiyin" aria-label="Permalink to &quot;3-topshiriq: To&#39;liq chiziqli algoritm loyihasi (24-dars) · qiyin&quot;">​</a></h2><ol><li><strong>«Kichik do&#39;kon kassa hisobi» loyihasi:</strong><ul><li>Foydalanuvchidan mahsulot narxini (<code>narx</code>) va olingan miqdorini (<code>soni</code>) so&#39;rang.</li><li>Umumiy summani hisoblang: <code>jami = narx * soni</code>.</li><li>Do&#39;kon 10% chegirma bermoqda: <code>chegirma = jami * 0.10</code>.</li><li>To&#39;lanishi kerak bo&#39;lgan yakuniy summani toping: <code>tolov = jami - chegirma</code>.</li><li>Konsolga hisob chekini quyidagicha chiqaring: <ul><li>Jami summa: ... so&#39;m</li><li>Chegirma (10%): ... so&#39;m</li><li>To&#39;lov summasi: ... so&#39;m</li></ul></li></ul></li><li>Loyihani <code>.fprg</code> kengaytmasida saqlang va uning blok-sxemasini daftaringizga chizing.</li></ol><hr><h2 id="baholash-mezoni" tabindex="-1">Baholash mezoni <a class="header-anchor" href="#baholash-mezoni" aria-label="Permalink to &quot;Baholash mezoni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Ball</th></tr></thead><tbody><tr><td>1-topshiriq: 3 ta tizimning IPO tahlili va salomlashish loyihasi</td><td style="text-align:center;">3</td></tr><tr><td>2-topshiriq: Ma&#39;lumot turlarini to&#39;g&#39;ri tanlash va Harorat konvertori</td><td style="text-align:center;">3</td></tr><tr><td>3-topshiriq: Do&#39;kon kassa hisobi loyihasi va blok-sxemani chizish</td><td style="text-align:center;">4</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>10 ball</strong></td></tr></tbody></table><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="tekshirish-ko-rsatmalari-va-yechimlar" tabindex="-1">Tekshirish ko&#39;rsatmalari va yechimlar <a class="header-anchor" href="#tekshirish-ko-rsatmalari-va-yechimlar" aria-label="Permalink to &quot;Tekshirish ko&#39;rsatmalari va yechimlar&quot;">​</a></h3><ol><li><strong>1-topshiriq tekshiruvi:</strong><ul><li>O&#39;quvchi IPO modelidagi farqlarni (Kiritish vs Jarayon vs Natija) aniq tushunganligiga e&#39;tibor qarating.</li><li>Flowgorithmda <code>&amp;</code> belgisi to&#39;g&#39;ri qo&#39;llangan bo&#39;lishi kerak.</li></ul></li><li><strong>2-topshiriq tekshiruvi:</strong><ul><li>O&#39;quvchilar soni — <code>Integer</code></li><li>Bo&#39;yi — <code>Real</code></li><li>Maktab nomi — <code>String</code></li><li>Keldimi/yo&#39;qmi — <code>Boolean</code></li><li>Non narxi — <code>Integer</code> yoki <code>Real</code></li><li>Harorat formulasida <code>Declare Real c, f</code> bo&#39;lishi shart, aks holda kasr qismlar yo&#39;qoladi.</li></ul></li><li><strong>3-topshiriq tekshiruvi:</strong><ul><li>Bloklar zanjiri chiziqli bo&#39;lishi kerak: Start → Declare → Input narx, soni → Assign jami → Assign chegirma → Assign tolov → Output xabarlar → End.</li><li>Amallar tartibida qavslar va foiz ko&#39;paytmasi to&#39;g&#39;ri ishlanganligini tekshirish.</li></ul></li></ol>',17))]),t("div",m,[t("h2",u,[l(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni-1","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 8-hafta<br><strong>Darslar:</strong> 22, 23, 24 (global); 1, 2, 3 (hafta ichida)</p><hr><h2 id="o-quvchilar-ro-yxati-va-baholar" tabindex="-1">O&#39;quvchilar ro&#39;yxati va baholar <a class="header-anchor" href="#o-quvchilar-ro-yxati-va-baholar" aria-label="Permalink to &quot;O&#39;quvchilar ro&#39;yxati va baholar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi ismi</th><th style="text-align:center;">D-22 (0–5)</th><th style="text-align:center;">D-23 (0–5)</th><th style="text-align:center;">D-24 (0–5)</th><th style="text-align:center;">Uyga vazifa (0–10)</th><th style="text-align:center;">Jami (0–25)</th><th>Izoh</th></tr></thead><tbody><tr><td></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="dars-baholari-har-bir-dars-uchun-0–5-ball" tabindex="-1">Dars baholari (har bir dars uchun: 0–5 ball) <a class="header-anchor" href="#dars-baholari-har-bir-dars-uchun-0–5-ball" aria-label="Permalink to &quot;Dars baholari (har bir dars uchun: 0–5 ball)&quot;">​</a></h2><h3 id="dars-22-flowalgorithm-orqali-dasturlash-tushunchalari-dastur-buyruq-kod-va-mantiq" tabindex="-1">Dars-22: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq <a class="header-anchor" href="#dars-22-flowalgorithm-orqali-dasturlash-tushunchalari-dastur-buyruq-kod-va-mantiq" aria-label="Permalink to &quot;Dars-22: Flowalgorithm orqali dasturlash tushunchalari: dastur, buyruq, kod va mantiq&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Maks</th></tr></thead><tbody><tr><td>Dastur, buyruq va kod o&#39;rtasidagi farqni tushuntira olishi</td><td style="text-align:center;">1</td></tr><tr><td>IPO modelini (Input — Process — Output) hayotiy misollarda ko&#39;rsatishi</td><td style="text-align:center;">2</td></tr><tr><td>Flowgorithmda oddiy matnli zanjir tuzib, <code>&amp;</code> orqali matnlarni birlashtirishi</td><td style="text-align:center;">1</td></tr><tr><td>Darsdagi faollik va savol-javob</td><td style="text-align:center;">1</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>5</strong></td></tr></tbody></table><h3 id="dars-23-flowalgorithmda-o-zgaruvchilar-va-ma-lumot-turlari-bilan-ishlash" tabindex="-1">Dars-23: Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash <a class="header-anchor" href="#dars-23-flowalgorithmda-o-zgaruvchilar-va-ma-lumot-turlari-bilan-ishlash" aria-label="Permalink to &quot;Dars-23: Flowalgorithmda o‘zgaruvchilar va ma’lumot turlari bilan ishlash&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Maks</th></tr></thead><tbody><tr><td>O&#39;zgaruvchi tushunchasi va xotiradagi o&#39;rnini to&#39;g&#39;ri izohlashi</td><td style="text-align:center;">1</td></tr><tr><td>O&#39;zgaruvchi nomlash qoidalariga (raqamsiz boshlanish, probelsiz) qat&#39;iy amal qilishi</td><td style="text-align:center;">1</td></tr><tr><td>4 ta turni (<code>Integer</code>, <code>Real</code>, <code>String</code>, <code>Boolean</code>) farqlab, to&#39;g&#39;ri <code>Declare</code> qilishi</td><td style="text-align:center;">2</td></tr><tr><td><code>Assign</code> bloki orqali qiymat berish va hisoblash</td><td style="text-align:center;">1</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>5</strong></td></tr></tbody></table><h3 id="dars-24-flowalgorithmda-chiziqli-algoritmlar-yaratish" tabindex="-1">Dars-24: Flowalgorithmda chiziqli algoritmlar yaratish <a class="header-anchor" href="#dars-24-flowalgorithmda-chiziqli-algoritmlar-yaratish" aria-label="Permalink to &quot;Dars-24: Flowalgorithmda chiziqli algoritmlar yaratish&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Maks</th></tr></thead><tbody><tr><td>Chiziqli algoritm qonuniyatlarini tushunishi (shartsiz, ketma-ket)</td><td style="text-align:center;">1</td></tr><tr><td>Arifmetik amallarni (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>) va qavslarni to&#39;g&#39;ri qo&#39;llashi</td><td style="text-align:center;">2</td></tr><tr><td>Geometrik va foiz formulalari asosida to&#39;liq ishlovchi blok-sxema loyihasini qurishi</td><td style="text-align:center;">1</td></tr><tr><td>F6 (Step) orqali xatolarni topa olishi va tuzatishi</td><td style="text-align:center;">1</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>5</strong></td></tr></tbody></table><hr><h2 id="uyga-vazifa-baholash-mezonlari-0–10-ball" tabindex="-1">Uyga vazifa baholash mezonlari (0–10 ball) <a class="header-anchor" href="#uyga-vazifa-baholash-mezonlari-0–10-ball" aria-label="Permalink to &quot;Uyga vazifa baholash mezonlari (0–10 ball)&quot;">​</a></h2><ul><li><strong>1-topshiriq (3 ball):</strong> 3 ta tizimning IPO tahlili va salomlashish loyihasini to&#39;g&#39;ri tuzish.</li><li><strong>2-topshiriq (3 ball):</strong> Ma&#39;lumot turlarini xatosiz aniqlash va Harorat konvertori loyihasi.</li><li><strong>3-topshiriq (4 ball):</strong> Do&#39;kon kassa hisobi loyihasining to&#39;liq chiziqli zanjirini tuzish va blok-sxemani daftarga chizish.</li></ul><hr><h2 id="hafta-yakunlari-va-tavsiyalar" tabindex="-1">Hafta yakunlari va tavsiyalar <a class="header-anchor" href="#hafta-yakunlari-va-tavsiyalar" aria-label="Permalink to &quot;Hafta yakunlari va tavsiyalar&quot;">​</a></h2><ul><li><strong>Kuchli tomonlar:</strong></li><li><strong>Qo&#39;shimcha ishlash kerak bo&#39;lgan mavzular:</strong></li><li><strong>Keyingi 9-hafta rejasi:</strong> Tarmoqlanuvchi algoritmlar va <code>Decision</code> (shart) bloki bilan tanishuv.</li></ul>',18))])])}const p=e(h,[["render",y]]);export{z as __pageData,p as default};
